do $do$
declare p jsonb := $pl$[{"k":"APBIO-MCQ-109","t":"Introduction to Macromolecules","s":"A cell joins eight separate monomers into one linear polymer by dehydration synthesis. A treatment then causes hydrolysis of exactly three different bonds connecting monomers in that polymer, with no further joining. Considering only these reactions, what final number of separate molecules and net change in water molecules are predicted relative to the start?","a":"B","c":[["A","Four separate molecules derived from the polymer; ten water molecules released overall.",false,"Water-total addition error: This counts both bond formation and bond cleavage as releasing water. The seven joining reactions release water, but the three hydrolysis reactions consume it. Fix: Subtract water consumed during hydrolysis from water released during dehydration synthesis."],["B","Four separate molecules derived from the polymer; four water molecules released overall.",true,"Joining eight monomers into one linear polymer forms seven bonds and releases seven water molecules. Hydrolyzing three bonds consumes three water molecules and divides the chain into four separate molecules, giving a net release of 7 − 3 = 4 water molecules."],["C","Four separate molecules derived from the polymer; four water molecules consumed overall.",false,"Water-direction reversal: This reverses the net water change. Dehydration synthesis releases seven water molecules, whereas hydrolysis consumes only three, so release exceeds consumption. Fix: Put water on the product side for dehydration synthesis and reactant side for hydrolysis."],["D","Three separate molecules derived from the polymer; four water molecules released overall.",false,"Bond-count versus fragment-count error: This equates the number of broken bonds with the number of resulting molecules. Each cleavage of a linear chain increases the number of separate molecules by one, starting from one polymer. Fix: Start with one chain and increase the molecule count by one for each cleavage."]]},{"k":"APBIO-MCQ-SV-109-v1","t":"Introduction to Macromolecules","s":"A laboratory sample initially contains two linear polymer chains, each composed of five monomers. One treatment hydrolyzes exactly five bonds connecting monomers in these chains. A second treatment then causes exactly two dehydration synthesis reactions, each joining two separate fragments. No other bonds form or break. Relative to the initial sample, how many separate polymer-derived molecules remain, and what is the net change in water molecules?","a":"C","c":[["A","Five polymer-derived molecules remain; seven water molecules are consumed overall.",false,"Water-total addition error: This treats both cleavage and joining as water-consuming reactions. Hydrolysis consumes five water molecules, but dehydration synthesis releases two, so their water changes oppose each other. Fix: Subtract the water released during joining from the water consumed during cleavage."],["B","Five polymer-derived molecules remain; three water molecules are released overall.",false,"Water-direction reversal: This gives the net water change the wrong direction. The five cleavage reactions consume more water than the two joining reactions release. Fix: Mark water as consumed for each cleavage and released for each joining before calculating."],["C","Five polymer-derived molecules remain; three water molecules are consumed overall.",true,"Five hydrolysis reactions increase the molecule count from two to seven and consume five water molecules. Two joining reactions reduce the count to five and release two water molecules, leaving a net consumption of 5 − 2 = 3 water molecules."],["D","Three polymer-derived molecules remain; three water molecules are consumed overall.",false,"Bond-count versus fragment-count error: This starts with five fragments because five bonds were broken, then subtracts two for joining. Cleavage adds fragments to the two chains already present, producing seven fragments before joining. Fix: Begin with the initial chain count, add each cleavage, and subtract each joining."]]},{"k":"APBIO-MCQ-SV-109-v2","t":"Introduction to Macromolecules","s":"In a bacterial cell, a linear polymer chain of six monomers is lengthened when five free monomers are added to its end one at a time by dehydration synthesis. An enzyme then hydrolyzes exactly four of the bonds linking monomers in the lengthened chain, and no other bonds form or break. Compared with the moment before lengthening began, how many separate molecules come from the chain, and what is the net water change?","a":"A","c":[["A","Five separate molecules from the chain; one water molecule released overall.",true,"Adding five monomers forms five bonds, each releasing one water molecule. Hydrolyzing four bonds consumes four water molecules and cuts the single 11-monomer chain into five pieces, so the net change is 5 − 4 = 1 water molecule released."],["B","Five separate molecules from the chain; nine water molecules released overall.",false,"Water-total addition error: this treats both joining and cleaving as releasing water. Dehydration synthesis releases five water molecules, but hydrolysis consumes four, so the totals must be subtracted. Fix: Subtract water used by hydrolysis from water released by dehydration synthesis."],["C","Five separate molecules from the chain; one water molecule consumed overall.",false,"Water-direction reversal: this flips which reaction releases water. Dehydration synthesis releases water and hydrolysis uses it, and five released exceeds four used, giving a net release. Fix: Write water as a product of dehydration synthesis and a reactant of hydrolysis before tallying."],["D","Four separate molecules from the chain; one water molecule released overall.",false,"Bond-count versus fragment-count error: this sets the number of pieces equal to the number of bonds cut. Cutting one linear chain once yields two pieces, so four cuts yield five. Fix: Start at one chain and add one molecule for each bond hydrolyzed."]]},{"k":"APBIO-MCQ-SV-109-v3","t":"Introduction to Macromolecules","s":"A plant cell starts with fifteen free monomers and uses dehydration synthesis to assemble them into three separate linear chains of five monomers each. An enzyme then hydrolyzes exactly four monomer-linking bonds, chosen anywhere among the three chains. No other bonds form or break. Compared with the fifteen free monomers at the start, how many separate molecules result, and what is the net change in water molecules?","a":"A","c":[["A","Seven separate molecules; eight water molecules released overall.",true,"Each five-monomer linear chain has 4 bonds, so building three chains takes 12 dehydration reactions and releases 12 water molecules. Each hydrolysis consumes one water and adds one molecule, giving 3 + 4 = 7 molecules and a net release of 12 − 4 = 8 water molecules."],["B","Seven separate molecules; sixteen water molecules released overall.",false,"Water-total addition error: this treats both bond formation and bond cleavage as releasing water. The 12 dehydration reactions release water, but the 4 hydrolysis reactions consume it. Fix: Subtract the water consumed by hydrolysis from the water released by dehydration synthesis."],["C","Seven separate molecules; eight water molecules consumed overall.",false,"Water-direction reversal: this flips the sign of the net change. Dehydration synthesis released 12 water molecules while hydrolysis used only 4, so release exceeds consumption. Fix: Place water as a product for dehydration synthesis and as a reactant for hydrolysis before totaling."],["D","Four separate molecules; eight water molecules released overall.",false,"Bond-count versus fragment-count error: this equates the number of bonds broken with the number of molecules present. The cell already had three chains, and each cleavage adds one more molecule to that count. Fix: Start from the number of chains and add one molecule for each bond hydrolyzed."]]},{"k":"APBIO-MCQ-110","t":"Carbohydrates","s":"Researchers study a mutant plant that cannot synthesize cellulose. Its cells form weak cell walls, and the plant cannot hold its stem upright. Which statement best explains this observation?","a":"A","c":[["A","Cellulose is a polysaccharide of glucose monomers covalently linked into long linear chains that give plant cell walls structural support.",true,"Cellulose is a carbohydrate polymer built from glucose monomers. Its function is structural, not energy storage. Its long linear chains reinforce the cell wall, so a plant that cannot make cellulose has weak walls and cannot support its stem."],["B","Cellulose is the main energy-storage polysaccharide in plants, so without it the cells lack the fuel needed to grow upright.",false,"This trap assumes every carbohydrate exists for energy and confuses cellulose with starch, the plant storage polysaccharide. The observation is a structural failure in the wall, not an energy shortage. Fix: Ask whether the observed defect is structural or energetic before choosing a polysaccharide's function."],["C","Cellulose is a monosaccharide that plant cells break down for quick energy, so the cells cannot fuel cell wall construction.",false,"This confuses monomer with polymer. Cellulose is a polysaccharide made of many glucose monomers, and it serves as a wall component rather than a quick energy source. Fix: Check whether a carbohydrate is a single sugar unit or a chain of many units."],["D","Cellulose is a protein whose folded amino acid chains form fibers, so without it the wall loses its folded protein framework.",false,"This misclassifies cellulose as a protein because it forms fibers. Cellulose is a carbohydrate made of glucose monomers, not amino acids joined by peptide bonds. Fix: Identify the monomer first: sugars build carbohydrates, amino acids build proteins."]]},{"k":"APBIO-MCQ-SV-110-v1","t":"Carbohydrates","s":"Researchers apply a treatment to pear skin that breaks down cellulose in its cell walls without changing the amount of stored starch. The treated skin is easier to puncture than untreated skin. Which explanation best connects cellulose's structure and function to this result?","a":"C","c":[["A","Cellulose is the main energy-storage carbohydrate in pear cells, so its breakdown leaves the skin without stored fuel to maintain its strength.",false,"The energy-only trap confuses cellulose's structural role with starch's storage role. The treatment damages a wall component while leaving stored starch unchanged. Fix: Match the affected carbohydrate to structural support or energy storage before explaining the result."],["B","Cellulose is a single sugar molecule used for immediate energy, so its breakdown prevents pear cells from fueling wall maintenance.",false,"The monomer–polymer confusion treats cellulose as one sugar unit. Cellulose is a polysaccharide containing many glucose units and functions as structural material in the wall. Fix: Check whether the named carbohydrate is one sugar unit or a polymer."],["C","Cellulose consists of many sugar monomers covalently joined into chains that reinforce cell walls, so breaking down those chains reduces the skin's strength.",true,"Cellulose's long chains of glucose monomers provide structural support in plant cell walls. Disrupting this carbohydrate framework makes the pear skin less resistant to puncture without requiring a change in energy storage."],["D","Cellulose is a protein made of folded amino acid chains, so its breakdown destroys the protein framework supporting the pear skin.",false,"The carbohydrate–protein misclassification mistakes a supporting material for a protein. Cellulose contains sugar monomers, not the amino acid monomers that build proteins. Fix: Identify the building units before assigning the material to a macromolecule class."]]},{"k":"APBIO-MCQ-SV-110-v2","t":"Carbohydrates","s":"A textile company spins cotton fibers into thread that resists breaking when pulled. The fiber walls contain abundant cellulose. Which statement best connects cellulose’s structure and function to the strength of the thread?","a":"B","c":[["A","Cellulose stores energy in cotton fibers, and this stored fuel gives the thread its resistance to breaking.",false,"The energy-only trap confuses cellulose’s structural role with starch’s storage role in plants. Resistance to pulling reflects physical reinforcement, not the amount of stored fuel. Fix: Decide whether the observation concerns mechanical support or energy storage."],["B","Cellulose contains many glucose units covalently joined into long, linear chains that provide structural reinforcement in the cotton fiber walls.",true,"Cellulose’s linked sugar units form a structural polysaccharide rather than an energy reserve. These chains reinforce the fiber walls, helping the cotton fibers withstand pulling when spun into thread."],["C","Cellulose is a single sugar molecule that supplies quick energy, allowing cotton fibers to resist pulling.",false,"The monomer–polymer confusion treats cellulose as one sugar unit instead of a chain of many units. Its contribution here is structural support, not quick energy delivery. Fix: Determine whether the named carbohydrate contains one sugar unit or many linked units."],["D","Cellulose consists of folded amino acid chains whose protein structure reinforces the cotton fibers.",false,"The fiber-means-protein trap classifies a material by its appearance rather than its building blocks. Cellulose contains glucose units, so it is a carbohydrate polymer, not a protein. Fix: Identify the building blocks before assigning a molecule to a macromolecule class."]]},{"k":"APBIO-MCQ-SV-110-v3","t":"Carbohydrates","s":"During spring growth, a maple tree uses much of the starch stored in its trunk, but the cellulose-rich walls of its cells continue to provide structural support. Which statement best explains why this support persists?","a":"C","c":[["A","Cellulose provides support by serving as the tree’s main energy-storage polysaccharide after the starch supply decreases.",false,"The energy-only trap confuses cellulose’s structural role with starch’s storage role. Continued wall support comes from cellulose as a building material, not from cellulose replacing an energy reserve. Fix: Match each polysaccharide to either energy storage or structural support before explaining the observation."],["B","Cellulose is a single sugar molecule that supplies quick energy for maintaining the tree’s supporting walls.",false,"The monomer–polymer trap treats cellulose as a monosaccharide. Cellulose consists of many linked glucose units and supports walls as a polymer, rather than acting as a single quick-energy sugar. Fix: Check whether the named carbohydrate contains one sugar unit or many linked units."],["C","Cellulose contains glucose units covalently joined into long, linear polysaccharide chains that reinforce cell walls independently of stored starch.",true,"The tree uses starch as an energy reserve, whereas cellulose serves as a structural material. Cellulose’s long polymer chains reinforce the walls, so using stored starch does not remove that reinforcement."],["D","Cellulose consists of folded amino acid chains whose protein fibers maintain the strength of the tree’s cell walls.",false,"The protein-misclassification trap assumes that a fibrous structural material must be a protein. Cellulose is a carbohydrate built from glucose units, not a chain of amino acids. Fix: Identify the building units before classifying a structural material as a carbohydrate or protein."]]},{"k":"APBIO-MCQ-111","t":"Carbohydrates","s":"A researcher wants to test whether cellulose contributes to structural support in plant tissue. A treatment selectively removes cellulose without removing starch or other polysaccharides. Which experimental design best tests this question?","a":"D","c":[["A","Randomly assign equal-sized strips from the same plant tissue to the treatment or an otherwise identical control solution, then compare the amount of starch stored in the strips.",false,"Energy-only misconception: Measuring stored starch addresses carbohydrate storage, not structural support. It does not determine whether removing cellulose changes tissue strength. Fix: Match the measured outcome to structural support by choosing a measure of strength."],["B","Apply the treatment to thin strips and an otherwise identical control solution to thick strips from the same plant tissue, then compare the force required to tear them.",false,"Confounded-variable trap: Strip thickness differs along with treatment and can affect tearing force. A strength difference therefore cannot be attributed specifically to cellulose removal. Fix: Keep strip dimensions equal across treatment and control groups."],["C","Apply the treatment to all equal-sized strips from the same plant tissue, then measure the force required to tear each strip and calculate the average.",false,"Missing-control trap: Averaging treated strips estimates their strength but provides no comparison showing whether cellulose removal changed it. Repeated measurements do not replace a control group. Fix: Include matched strips exposed to the same conditions without the cellulose-removing agent."],["D","Randomly assign equal-sized strips from the same plant tissue to the treatment or an otherwise identical solution without the cellulose-removing agent, then compare the force required to tear the strips.",true,"Cellulose is a polysaccharide with a structural role in plants, so tearing force is a relevant measure of support. Matched strips and a control solution help isolate the effect of cellulose removal on tissue strength."]]},{"k":"APBIO-MCQ-SV-111-v1","t":"Carbohydrates","s":"A student makes starch-based packaging panels and asks whether adding cellulose increases their ability to support a load without bending. The student can prepare mixtures with or without added cellulose and mold them into panels. Which procedure would best answer the question?","a":"A","c":[["A","Prepare multiple panels with and without added cellulose, keeping panel dimensions and drying conditions identical, and compare the loads needed to bend them by a fixed amount.",true,"Cellulose is a structural polysaccharide, and resistance to bending measures structural support. Matching dimensions and drying conditions while including panels without added cellulose helps isolate the effect of cellulose."],["B","Prepare multiple panels with and without added cellulose, keeping panel dimensions and drying conditions identical, and compare the amounts of starch present.",false,"Energy-only misconception: Measuring an energy-storage carbohydrate does not measure the panels’ structural support. Starch content alone cannot establish whether cellulose improves resistance to bending. Fix: Choose a measured outcome that directly tests resistance to bending."],["C","Prepare thick panels with added cellulose and thin panels without it, keeping drying conditions identical, and compare the loads needed to bend them by a fixed amount.",false,"Confounded-variable trap: Thickness changes along with cellulose addition and can affect resistance to bending. The results would not isolate cellulose’s contribution. Fix: Match panel thickness across groups before comparing their resistance to bending."],["D","Prepare multiple identical panels containing added cellulose, keep drying conditions identical, and calculate the average load needed to bend them by a fixed amount.",false,"Missing-control trap: These measurements describe panels containing cellulose but cannot show whether adding it improves support. Replication does not supply the missing comparison. Fix: Add matched panels made without cellulose as the comparison group."]]}]$pl$::jsonb; r jsonb; c jsonb; v_ci uuid; v_civ uuid; n int;
begin
  if jsonb_array_length(p) <> 10 then raise exception 'chunk size'; end if;
  if exists (select 1 from app.content_items ci where ci.exam_pack_version_id='2d88ba5e-a6a3-43b8-bfae-9e5505a178a7' and ci.content_key in (select x->>'k' from jsonb_array_elements(p) x))
    then raise exception 'chunk already loaded'; end if;
  for r in select * from jsonb_array_elements(p) loop
    insert into app.content_items (exam_pack_version_id, content_key, item_type, title, status)
    values ('2d88ba5e-a6a3-43b8-bfae-9e5505a178a7', r->>'k', 'mcq', r->>'t', 'draft') returning id into v_ci;
    insert into app.content_item_versions (content_item_id, version_num, stem, stimulus, content_hash, status, review_status, canonical_answer_1)
    values (v_ci, 1, r->>'s', null, md5(r->>'k'), 'draft', 'tutor_review_pending', r->>'a') returning id into v_civ;
    for c in select * from jsonb_array_elements(r->'c') loop
      insert into app.mcq_choices (content_item_version_id, choice_key, choice_text, is_correct, rationale)
      values (v_civ, c->>0, c->>1, (c->>2)::boolean, c->>3);
    end loop;
  end loop;
  select count(*) into n from app.content_items ci join app.content_item_versions v on v.content_item_id=ci.id join app.mcq_choices m on m.content_item_version_id=v.id
   where ci.exam_pack_version_id='2d88ba5e-a6a3-43b8-bfae-9e5505a178a7' and ci.status='draft' and ci.content_key in (select x->>'k' from jsonb_array_elements(p) x);
  if n <> 40 then raise exception 'chunk 4: expected 40 choice rows, got %', n; end if;
  raise notice 'chunk 4: loaded 10 draft items';
end
$do$;
